      "title": "German Internet Panel (GIP)",
      "url_or_doi": "https://www.uni-mannheim.de/gip/",
      "justification": "The German Internet Panel (GIP) is a long-term, probability-based online panel study operated by the University of Mannheim in cooperation with GESIS. Running bi-monthly through the 2020s, it collects internet-based survey data from Germany on individual attitudes and preferences relevant to political and economic decision-making, covering employment, social welfare policy, political behaviour, health, migration, and government policy reforms."
    },
    {
      "title": "GESIS Panel Standard Edition",
      "url_or_doi": "https://doi.org/10.4232/1.14285",
      "justification": "The GESIS Panel is an open probability-based mixed-mode (predominantly web-based) longitudinal survey of the general population in Germany running through the 2020s. It regularly measures political attitudes and behaviour, economic decision-making, employment status, social welfare preferences, health conditions, and views on migration and social service availability."
    },
    {
      "title": "German Longitudinal Election Study (GLES) Panel",
      "url_or_doi": "https://www.gesis.org/en/gles/gles-panel",
      "justification": "The GLES Panel is a primary web-based longitudinal survey tracking political and societal attitudes, political behaviour, voting choices, government system evaluations, and economic preferences among eligible voters in Germany throughout the 2020s."
    },
    {
      "title": "GESIS Panel Special Survey on the Coronavirus SARS-CoV-2 Outbreak in Germany",
      "url_or_doi": "https://doi.org/10.4232/1.13520",
      "justification": "Conducted in 2020 using the GESIS Panel online infrastructure, this high-frequency panel dataset collects individual data in Germany regarding specific diseases and medical conditions (COVID-19), health behaviors, trust in government, political attitudes, employment changes, and social welfare support."
    }
  ]
}
